// API一覧
// [UnionFind]
// UnionFind(n=0): n要素を独立成分として構築。O(n+1)時間・領域、n<=INT_MAX。
// root(i)/leader(i): 代表、unite(a,b): 結合（戻り値なし）、merge(a,b): 新規結合ならtrue。償却O(α(n+1))。
// issame(a,b)/same(a,b): 同一成分か、size(i): 成分サイズ。償却O(α(n+1))。探索時に経路を圧縮する。
// size()/empty()/component_count(): 全要素数/空か/成分数、O(1)。groups(): 頂点昇順の成分一覧、O(1+n α(n+1))償却。
// reset(n)/reset(): n要素/現在の要素数へ初期化。容量を再利用、O(旧n+n+1)上界。確保失敗時は元を保つ。
// clear(): 空へ戻して容量保持、O(旧n+1)上界、noexcept。swap(other): 内容交換、O(1)、noexcept。
// コピーはO(n+1)で独立、移動元は空。自己代入・自己ムーブは内容を保つ。

#include <algorithm>
#include <cstddef>
#include <memory>
#if !defined(SIRKIT_DISABLE_SIMD) && defined(__clang__) && !defined(__AVX2__) && (defined(__x86_64__) || defined(__i386__))
#include <immintrin.h>
#endif
#include <limits>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>

#if !defined(SIRKIT_DISABLE_SIMD) && defined(__clang__) && !defined(__AVX2__) && (defined(__x86_64__) || defined(__i386__))
#ifndef SIRKIT_UNION_GROUP_ROOTS_AVX2_DEFINED
#define SIRKIT_UNION_GROUP_ROOTS_AVX2_DEFINED
namespace reinsirk::detail {
template<bool Compress>
[[gnu::target("avx2")]]
inline void GatherGroupRoots(const int* parents, int* leaders, std::size_t n, int* writable = nullptr) {
    std::size_t i = 0;
    auto indices = _mm256_setr_epi32(0,1,2,3,4,5,6,7);
    const auto negative_one = _mm256_set1_epi32(-1);
    for (; i + 8 <= n; i += 8) {
        const auto original = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(parents+i));
        const auto nonroot = _mm256_cmpgt_epi32(original, negative_one);
        auto root = _mm256_blendv_epi8(indices, original, nonroot);
        // 根のlaneは再読込せず、未解決の親だけを追う。
