        _mm256_storeu_si256(reinterpret_cast<__m256i*>(leaders+i), root);
        if constexpr (Compress)
            _mm256_storeu_si256(reinterpret_cast<__m256i*>(writable+i), _mm256_blendv_epi8(original,root,nonroot));
