#ifndef SIRKIT_UNION_GROUP_FULL_COMPRESSION_AVX2_DEFINED
#define SIRKIT_UNION_GROUP_FULL_COMPRESSION_AVX2_DEFINED
namespace reinsirk::detail {
[[gnu::target("avx2")]]
inline void GatherAndCompressGroupRoots(int* parents, int* leaders, std::size_t n) {
    std::size_t i = 0;
    auto indices = _mm256_setr_epi32(0,1,2,3,4,5,6,7);
    const auto negative_one = _mm256_set1_epi32(-1);
    for (; i + 8 <= n; i += 8) {
        const auto original = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(parents+i));
        const auto nonroot = _mm256_cmpgt_epi32(original, negative_one);
        auto root = _mm256_blendv_epi8(indices, original, nonroot);
        auto active = nonroot;
        while (!_mm256_testz_si256(active, active)) {
            const auto next = _mm256_mask_i32gather_epi32(negative_one, parents, root, active, 4);
            active = _mm256_cmpgt_epi32(next, negative_one);
            root = _mm256_blendv_epi8(root, next, active);
        }
        _mm256_storeu_si256(reinterpret_cast<__m256i*>(leaders+i), root);
        // 途中の頂点も圧縮し、後続ブロックによる同じ長い経路の再走査を避ける。
        const auto changed = _mm256_andnot_si256(_mm256_cmpeq_epi32(original, root), nonroot);
        unsigned mask = static_cast<unsigned>(_mm256_movemask_ps(_mm256_castsi256_ps(changed)));
        while (mask) {
            const auto lane = std::countr_zero(mask);
            mask &= mask - 1;
            const int r = leaders[i + lane];
            int v = static_cast<int>(i + lane);
            int next = parents[v];
            while (next >= 0 && next != r) {
                parents[v] = r;
                v = next; next = parents[v];
            }
        }
        indices = _mm256_add_epi32(indices, _mm256_set1_epi32(8));
    }
    for (; i < n; ++i) {
        int r = static_cast<int>(i);
        while (parents[r] >= 0) r = parents[r];
        leaders[i] = r;
        int v = static_cast<int>(i), next = parents[v];
        while (next >= 0 && next != r) {
            parents[v] = r;
            v = next; next = parents[v];
        }
    }
}
} // namespace reinsirk::detail
