int main(int argc,char**argv){if(argc!=7)return 2;const int n=std::atoi(argv[1]),width=std::atoi(argv[2]),shape=std::atoi(argv[3]),cold=std::atoi(argv[4]),reps=std::atoi(argv[5]),seed=std::atoi(argv[6]);UnionFind original(n);std::vector<int> order(n);std::iota(order.begin(),order.end(),0);if(shape==2){std::mt19937 rng(seed);std::shuffle(order.begin(),order.end(),rng);}for(int begin=0;begin<n;begin+=width){const int end=std::min(n,begin+width);if(shape==1){for(int j=begin+1;j<end;++j)original.merge(order[begin],order[j]);}else for(int step=1;step<end-begin;step*=2)for(int j=begin;j+step<end;j+=2*step)original.merge(order[j],order[j+step]);}UnionFind uf=original;if(!cold)for(int i=0;i<5;++i)(void)uf.groups();std::clock_t elapsed=0;std::uint64_t sum=0;for(int rep=0;rep<reps;++rep){if(cold)uf=original;auto begin=std::clock();auto gs=uf.groups();auto end=std::clock();elapsed+=end-begin;sum+=gs.size();for(const auto&g:gs){sum+=g.size();for(int v:g)sum+=v;}}std::printf("%.9f %ju\n",double(elapsed)*1000/CLOCKS_PER_SEC,static_cast<std::uintmax_t>(sum));}

