// SPDX-License-Identifier: CC0-1.0
#ifndef SIRKIT_UF_SOURCE
#define SIRKIT_UF_SOURCE "/tmp/uf_round2_20261030/groups_full.hpp"
#endif
#include SIRKIT_UF_SOURCE
#include <algorithm>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <vector>
static std::uint64_t checks=0;
static void require(bool x){++checks;if(!x)std::abort();}
static auto expected_groups(const std::vector<int>&label){std::vector<std::vector<int>>out(label.size());for(int v=0;v<static_cast<int>(label.size());++v)out[label[v]].push_back(v);std::erase_if(out,[](const auto&g){return g.empty();});return out;}
static std::uint64_t old_source_only_steps(std::vector<int>parents){std::uint64_t steps=0;for(int i=0;i<static_cast<int>(parents.size());++i){int root=i;while(parents[root]>=0){++steps;root=parents[root];}if(i!=root)parents[i]=root;}return steps;}
// 実装の計時ではなく、バッチ後の途中圧縮に対する辺数課金の補助モデル。
static void linear_batch_model(std::vector<int>parents,const std::vector<int>&labels,const std::vector<int>&sizes){
 std::uint64_t reads=0,writes=0;const int n=static_cast<int>(parents.size());
 for(int first=0;first<n;first+=8){const int end=std::min(n,first+8);int roots[8];for(int i=first;i<end;++i){int root=i;while(parents[root]>=0){++reads;root=parents[root];}roots[i-first]=root;}for(int i=first;i<end;++i){const int root=roots[i-first];int v=i,next=parents[v];while(next>=0&&next!=root){++writes;parents[v]=root;v=next;next=parents[v];}}}
 require(reads<=std::uint64_t{9}*static_cast<std::uint64_t>(n));require(writes<=static_cast<std::uint64_t>(n));for(int v=0;v<n;++v)require(parents[v]==(labels[v]==v?-sizes[v]:labels[v]));
}
static void exercise(int block,int tail,int order){
 const int n=2*block+tail;std::vector<int>logical(n);std::iota(logical.begin(),logical.end(),0);
 if(order==0)std::stable_sort(logical.begin(),logical.end(),[&](int a,int b){return (a%block%2)>(b%block%2);});
 else std::stable_sort(logical.begin(),logical.end(),[&](int a,int b){const auto da=std::popcount(static_cast<unsigned>(a%block)),db=std::popcount(static_cast<unsigned>(b%block));return order==1?da>db:da<db;});
 std::vector<int>id(n),label(n),size(n,0),parents(n,-1);for(int v=0;v<n;++v)id[logical[v]]=v;
 for(int first=0;first<n;first+=block){const int end=std::min(n,first+block),root=id[first];size[root]=end-first;for(int i=first;i<end;++i){label[id[i]]=root;const unsigned local=static_cast<unsigned>(i-first);parents[id[i]]=local?id[i-static_cast<int>(local&(~local+1))]:first-end;}}
 if(order==0){const auto k=std::bit_width(static_cast<unsigned>(block))-1;require(old_source_only_steps(parents)>=static_cast<std::uint64_t>(block)*(k+1)/2);}
 linear_batch_model(parents,label,size);
#if defined(SIRKIT_UNION_GROUP_FULL_COMPRESSION_AVX2_DEFINED) && !defined(SIRKIT_DISABLE_SIMD) && defined(__clang__) && !defined(__AVX2__) && (defined(__x86_64__) || defined(__i386__))
 if(__builtin_cpu_supports("avx2")){auto compressed=parents;std::vector<int>leaders(n,-123);reinsirk::detail::GatherAndCompressGroupRoots(compressed.data(),leaders.data(),compressed.size());require(leaders==label);for(int v=0;v<n;++v)require(compressed[v]==(label[v]==v?-size[v]:label[v]));const auto before=compressed;std::fill(leaders.begin(),leaders.end(),-123);reinsirk::detail::GatherAndCompressGroupRoots(compressed.data(),leaders.data(),compressed.size());require(leaders==label&&compressed==before);}
#endif
 UnionFind uf(n);
 // 根を引数にしてbinomial木を構築する。groups前にroot/size等を呼ばない。
 for(int first=0;first<n;first+=block){const int end=std::min(n,first+block);for(int stride=1;stride<end-first;stride*=2)for(int i=first;i+stride<end;i+=stride*2)require(uf.merge(id[i],id[i+stride]));}
 const auto expected=expected_groups(label);require(expected.size()>=2);require(uf.groups()==expected);for(int repeat=0;repeat<3;++repeat)require(uf.groups()==expected);
 auto inspect=[&]{std::vector<int>counts(n);for(int root:label)++counts[root];for(int v=0;v<n;++v){require(uf.root(v)==label[v]);require(uf.size(v)==counts[label[v]]);}require(uf.groups()==expected_groups(label));};inspect();
 auto merge=[&](int a,int b){const int x=label[a],y=label[b];if(x==y){require(!uf.merge(a,b));return;}int first=x,second=y;const auto sx=std::count(label.begin(),label.end(),x),sy=std::count(label.begin(),label.end(),y);if(sx<sy)std::swap(first,second);for(auto&v:label)if(v==second)v=first;require(uf.merge(a,b));};
 merge(id[block-1],id[2*block-1]);merge(id[2*block-1],id[block-1]);if(tail)merge(id[2*block],id[block-1]);inspect();
}
int main(){for(int block:{2,8,64,128,256,2048,8192})for(int tail:{0,1,7})for(int order:{0,1,2})exercise(block,tail,order);std::printf("PASS leaf/depth ordered binomial groups, roots/sizes/full compression, linear edge model checks=%ju\n",static_cast<std::uintmax_t>(checks));}
